CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_campaign_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_campaign_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_campaign_admin() TO authenticated;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_campaign_admin());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER campaign_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE TABLE public.campaign_houses (id text PRIMARY KEY, name text NOT NULL, castle text, details text NOT NULL DEFAULT '', crest text, source text NOT NULL DEFAULT '', folder_id text, season integer NOT NULL DEFAULT 2, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.campaign_houses TO anon,authenticated; GRANT INSERT,UPDATE ON public.campaign_houses TO authenticated; GRANT ALL ON public.campaign_houses TO service_role;
ALTER TABLE public.campaign_houses ENABLE ROW LEVEL SECURITY;
CREATE POLICY houses_read ON public.campaign_houses FOR SELECT TO anon,authenticated USING(active AND season=2);
CREATE POLICY houses_admin_read ON public.campaign_houses FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE POLICY houses_admin_write ON public.campaign_houses FOR ALL TO authenticated USING(public.is_campaign_admin()) WITH CHECK(public.is_campaign_admin());
CREATE TABLE public.campaign_players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE, name text NOT NULL, folder_id text, details text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.campaign_players TO authenticated; GRANT ALL ON public.campaign_players TO service_role;
ALTER TABLE public.campaign_players ENABLE ROW LEVEL SECURITY;
CREATE POLICY players_read ON public.campaign_players FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_campaign_admin());
CREATE POLICY players_admin_write ON public.campaign_players FOR ALL TO authenticated USING(public.is_campaign_admin()) WITH CHECK(public.is_campaign_admin());
CREATE TABLE public.house_memberships (player_id uuid REFERENCES public.campaign_players(id), house_id text REFERENCES public.campaign_houses(id), can_edit boolean NOT NULL DEFAULT true, authorized_by uuid NOT NULL DEFAULT auth.uid(), authorized_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(player_id,house_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.house_memberships TO authenticated; GRANT ALL ON public.house_memberships TO service_role;
ALTER TABLE public.house_memberships ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_player_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.campaign_players WHERE user_id=auth.uid() $$;
CREATE FUNCTION public.in_campaign_house(h text, edit_required boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.house_memberships m JOIN public.campaign_players p ON p.id=m.player_id WHERE p.user_id=auth.uid() AND m.house_id=h AND (NOT edit_required OR m.can_edit)) $$;
REVOKE ALL ON FUNCTION public.my_player_id(),public.in_campaign_house(text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_player_id(),public.in_campaign_house(text,boolean) TO authenticated;
CREATE POLICY membership_read ON public.house_memberships FOR SELECT TO authenticated USING(player_id=public.my_player_id() OR public.is_campaign_admin());
CREATE POLICY membership_admin ON public.house_memberships FOR ALL TO authenticated USING(public.is_campaign_admin()) WITH CHECK(public.is_campaign_admin());
CREATE TABLE public.campaign_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), house_id text REFERENCES public.campaign_houses(id), player_id uuid REFERENCES public.campaign_players(id), visibility text NOT NULL CHECK(visibility IN ('player','house','gm')), kind text NOT NULL CHECK(kind IN ('document','character','details')), title text NOT NULL, content text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, created_by uuid NOT NULL DEFAULT auth.uid(), updated_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), sync_state text NOT NULL DEFAULT 'pending' CHECK(sync_state IN ('pending','synced','error','conflict')), last_synced_at timestamptz, CHECK((visibility='player' AND player_id IS NOT NULL) OR (visibility='house' AND house_id IS NOT NULL) OR visibility='gm'));
GRANT SELECT,INSERT ON public.campaign_records TO authenticated; GRANT ALL ON public.campaign_records TO service_role;
ALTER TABLE public.campaign_records ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_record(r public.campaign_records) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (r.visibility='player' AND r.player_id=public.my_player_id()) OR (r.visibility='house' AND public.in_campaign_house(r.house_id)) $$;
CREATE FUNCTION public.can_edit_record(r public.campaign_records) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (r.visibility='player' AND r.player_id=public.my_player_id() AND public.in_campaign_house(r.house_id,true)) OR (r.visibility='house' AND public.in_campaign_house(r.house_id,true)) $$;
CREATE POLICY records_read ON public.campaign_records FOR SELECT TO authenticated USING(public.can_read_record(campaign_records));
CREATE POLICY records_insert ON public.campaign_records FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND updated_by=auth.uid() AND version=1 AND sync_state='pending' AND last_synced_at IS NULL AND public.can_edit_record(campaign_records));
CREATE TABLE public.record_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid REFERENCES public.campaign_records(id), version integer NOT NULL, snapshot jsonb NOT NULL, author uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(record_id,version));
GRANT SELECT ON public.record_versions TO authenticated; GRANT ALL ON public.record_versions TO service_role;
ALTER TABLE public.record_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_read ON public.record_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.campaign_records r WHERE r.id=record_id));
CREATE TABLE public.campaign_letters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_player_id uuid REFERENCES public.campaign_players(id), sender_user_id uuid NOT NULL DEFAULT auth.uid(), sender_name text NOT NULL, recipient_player_id uuid REFERENCES public.campaign_players(id), recipient_house_id text REFERENCES public.campaign_houses(id), subject text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sync_state text NOT NULL DEFAULT 'pending', last_synced_at timestamptz, CHECK(num_nonnulls(recipient_player_id,recipient_house_id)=1));
GRANT SELECT ON public.campaign_letters TO authenticated; GRANT ALL ON public.campaign_letters TO service_role;
ALTER TABLE public.campaign_letters ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.letter_recipient(l public.campaign_letters) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (l.recipient_player_id=public.my_player_id()) OR (l.recipient_player_id IS NULL AND public.in_campaign_house(l.recipient_house_id)) $$;
CREATE FUNCTION public.can_read_letter(l public.campaign_letters) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR l.sender_user_id=auth.uid() OR coalesce(public.letter_recipient(l),false) $$;
CREATE POLICY letters_read ON public.campaign_letters FOR SELECT TO authenticated USING(public.can_read_letter(campaign_letters));
CREATE TABLE public.letter_receipts (letter_id uuid REFERENCES public.campaign_letters(id), user_id uuid NOT NULL DEFAULT auth.uid(), read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(letter_id,user_id));
GRANT SELECT,INSERT ON public.letter_receipts TO authenticated; GRANT ALL ON public.letter_receipts TO service_role;
ALTER TABLE public.letter_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipts_read ON public.letter_receipts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_campaign_admin());
CREATE POLICY receipts_insert ON public.letter_receipts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=letter_id AND public.letter_recipient(l)));
CREATE TABLE public.letter_replies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), letter_id uuid NOT NULL REFERENCES public.campaign_letters(id), author_user_id uuid NOT NULL DEFAULT auth.uid(), author_player_id uuid REFERENCES public.campaign_players(id), author_name text NOT NULL, house_id text REFERENCES public.campaign_houses(id), recipient_user_id uuid NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), idempotency_key uuid NOT NULL, sync_state text NOT NULL DEFAULT 'pending', last_synced_at timestamptz, UNIQUE(author_user_id,idempotency_key));
GRANT SELECT ON public.letter_replies TO authenticated; GRANT ALL ON public.letter_replies TO service_role;
ALTER TABLE public.letter_replies ENABLE ROW LEVEL SECURITY;
CREATE POLICY replies_read ON public.letter_replies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=letter_id));
CREATE TABLE public.sync_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), last_attempt_at timestamptz, UNIQUE(entity_type,entity_id,version));
GRANT SELECT ON public.sync_outbox TO authenticated; GRANT ALL ON public.sync_outbox TO service_role;
ALTER TABLE public.sync_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY outbox_admin_read ON public.sync_outbox FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE TABLE public.sync_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid REFERENCES public.campaign_records(id), site_snapshot jsonb NOT NULL, folder_snapshot jsonb NOT NULL, resolved_at timestamptz, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.sync_conflicts TO authenticated; GRANT ALL ON public.sync_conflicts TO service_role;
ALTER TABLE public.sync_conflicts ENABLE ROW LEVEL SECURITY;
CREATE POLICY conflicts_admin_read ON public.sync_conflicts FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE FUNCTION public.record_audit_enqueue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.record_versions(record_id,version,snapshot,author) VALUES(NEW.id,NEW.version,to_jsonb(NEW),NEW.updated_by); INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) VALUES('record',NEW.id,NEW.version,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER record_audit AFTER INSERT OR UPDATE OF content,title ON public.campaign_records FOR EACH ROW EXECUTE FUNCTION public.record_audit_enqueue();
CREATE FUNCTION public.mail_enqueue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.sync_outbox(entity_type,entity_id,payload) VALUES(TG_ARGV[0],NEW.id,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER letter_enqueue AFTER INSERT ON public.campaign_letters FOR EACH ROW EXECUTE FUNCTION public.mail_enqueue('letter');
CREATE TRIGGER reply_enqueue AFTER INSERT ON public.letter_replies FOR EACH ROW EXECUTE FUNCTION public.mail_enqueue('reply');
CREATE FUNCTION public.save_campaign_record(p_id uuid,p_version integer,p_title text,p_content text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.campaign_records; BEGIN SELECT * INTO r FROM public.campaign_records WHERE id=p_id FOR UPDATE; IF NOT FOUND OR NOT public.can_edit_record(r) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF r.version<>p_version THEN RAISE EXCEPTION 'Conflito de versão: recarregue antes de salvar. Sua edição não foi descartada.'; END IF; UPDATE public.campaign_records SET title=p_title,content=p_content,version=version+1,updated_by=auth.uid(),updated_at=now(),sync_state='pending' WHERE id=p_id RETURNING * INTO r; RETURN to_jsonb(r); END $$;
CREATE FUNCTION public.send_campaign_letter(p_player uuid,p_house text,p_subject text,p_content text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o administrador pode enviar novas missivas'; END IF; SELECT id INTO lid FROM public.campaign_letters WHERE id=p_key AND sender_user_id=auth.uid(); IF FOUND THEN RETURN lid; END IF; IF btrim(p_subject)='' OR btrim(p_content)='' THEN RAISE EXCEPTION 'Preencha assunto e conteúdo'; END IF; INSERT INTO public.campaign_letters(id,sender_user_id,sender_name,recipient_player_id,recipient_house_id,subject,content) VALUES(p_key,auth.uid(),'Mestre',p_player,p_house,p_subject,p_content) RETURNING id INTO lid; RETURN lid; END $$;
CREATE FUNCTION public.reply_campaign_letter(p_letter uuid,p_content text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; rid uuid; pname text; BEGIN SELECT * INTO l FROM public.campaign_letters WHERE id=p_letter FOR UPDATE; IF NOT FOUND OR NOT coalesce(public.letter_recipient(l),false) THEN RAISE EXCEPTION 'Você não é destinatário desta missiva'; END IF; IF btrim(p_content)='' THEN RAISE EXCEPTION 'Escreva a resposta'; END IF; SELECT id INTO rid FROM public.letter_replies WHERE author_user_id=auth.uid() AND idempotency_key=p_key; IF FOUND THEN RETURN rid; END IF; SELECT name INTO pname FROM public.campaign_players WHERE id=public.my_player_id(); INSERT INTO public.letter_replies(letter_id,author_user_id,author_player_id,author_name,house_id,recipient_user_id,content,idempotency_key) VALUES(l.id,auth.uid(),public.my_player_id(),coalesce(pname,'Jogador'),l.recipient_house_id,l.sender_user_id,p_content,p_key) RETURNING id INTO rid; INSERT INTO public.letter_receipts(letter_id,user_id) VALUES(l.id,auth.uid()) ON CONFLICT DO NOTHING; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.save_campaign_record(uuid,integer,text,text),public.send_campaign_letter(uuid,text,text,text,uuid),public.reply_campaign_letter(uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_campaign_record(uuid,integer,text,text),public.send_campaign_letter(uuid,text,text,text,uuid),public.reply_campaign_letter(uuid,text,uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.campaign_records,public.campaign_letters,public.letter_replies,public.letter_receipts,public.house_memberships;
COMMENT ON TABLE public.sync_outbox IS 'Durable versioned outbox; provider processing disabled until verified folder connection is configured. Never implies successful external sync.';